// n8n Function node: "Validate"
// Fail-closed gateway for ephemeral ingestion. Runs before any extract/embed/INSERT.
const fs = require('fs');
const path = require('path');

// n8n varies: payload may be at $json or $json.body
const src = ($json && $json.body) ? $json.body : $json;

const conversation_id = src.conversation_id;
const tenant_id       = src.tenant_id;
const file_path       = src.file_path;
const source_name     = src.source_name;
const rawTtl          = src.ttl_seconds;

// 1. Required fields (tenant_id is the isolation gate -- never proceed without it)
const required = { conversation_id, tenant_id, file_path, source_name };
for (const [key, val] of Object.entries(required)) {
  if (val === undefined || val === null || (typeof val === 'string' && val.trim() === '')) {
    throw new Error(`Missing required field: ${key}`);
  }
}

// 2. Path-traversal guard -- resolved path must live under /tmp or /uploads
const resolved = path.resolve(String(file_path));
const allowedRoots = ['/tmp/', '/uploads/'];
const underAllowedRoot = allowedRoots.some(root => resolved.startsWith(root));
if (!underAllowedRoot) {
  throw new Error(`file_path outside allowed roots (/tmp, /uploads): ${resolved}`);
}

// 3. Size cap -- 10 MB (MAX_WHATSAPP_UPLOAD_BYTES). statSync also surfaces missing files.
const MAX_BYTES = 10 * 1024 * 1024; // 10485760
let stat;
try {
  stat = fs.statSync(resolved);
} catch (e) {
  throw new Error(`Cannot stat file_path: ${resolved} (${e.message})`);
}
if (!stat.isFile()) {
  throw new Error(`file_path is not a regular file: ${resolved}`);
}
if (stat.size > MAX_BYTES) {
  throw new Error(`File exceeds 10 MB limit: ${stat.size} bytes`);
}

// 4. TTL bounds -- default 3600; if provided must be an integer in [60, 86400]
let ttl_seconds = 3600;
if (rawTtl !== undefined && rawTtl !== null && rawTtl !== '') {
  const n = Number(rawTtl);
  if (!Number.isFinite(n) || !Number.isInteger(n)) {
    throw new Error(`ttl_seconds must be an integer: ${rawTtl}`);
  }
  if (n < 60 || n > 86400) {
    throw new Error(`ttl_seconds out of range [60, 86400]: ${n}`);
  }
  ttl_seconds = n;
}

return [{
  json: {
    conversation_id: String(conversation_id),
    tenant_id: String(tenant_id),
    file_path: resolved,
    source_name: String(source_name),
    ttl_seconds,
  },
}];

// n8n Function node: "Extract Text"
// env: NODE_FUNCTION_ALLOW_BUILTIN=fs,path,os,child_process
//      NODE_FUNCTION_ALLOW_EXTERNAL=pdf-parse,mammoth
// container: poppler-utils (pdftoppm) required for scanned-PDF OCR (R1)
const fs = require('fs');
const path = require('path');
const os = require('os');
const { execFileSync } = require('child_process');
const pdfParse = require('pdf-parse');
const mammoth = require('mammoth');

const input = items[0].json;
const { conversation_id, tenant_id, source_name, ttl_seconds } = input;
const filePath = input.file_path;

// Infer type from extension (Validate already guaranteed existence + path safety)
const ext = path.extname(source_name || filePath).toLowerCase().replace(/^\./, '');
const SUPPORTED = ['pdf', 'docx', 'txt', 'png', 'jpg', 'jpeg'];
if (!SUPPORTED.includes(ext)) {
  throw new Error(`Unsupported file type: .${ext}`);   // -> 422 (validation)
}

const TEXT_THRESHOLD = 20;   // chars; a PDF below this is treated as scanned
const passthrough = { conversation_id, tenant_id, source_name, ttl_seconds };
const dataUrl = (buf, mime) => `data:${mime};base64,${buf.toString('base64')}`;
const pageNum = f => parseInt((f.match(/(\d+)\.png$/) || [])[1] || '0', 10);

let out;
try {
  if (ext === 'txt') {
    out = { ...passthrough, source_type: 'txt', text: fs.readFileSync(filePath, 'utf8'),
            needs_ocr: false, page_count: 1, images: [] };

  } else if (ext === 'docx') {
    const { value } = await mammoth.extractRawText({ path: filePath });
    out = { ...passthrough, source_type: 'docx', text: value || '',
            needs_ocr: false, page_count: 1, images: [] };

  } else if (ext === 'pdf') {
    const parsed = await pdfParse(fs.readFileSync(filePath));
    const text = (parsed.text || '').trim();
    if (text.length >= TEXT_THRESHOLD) {
      out = { ...passthrough, source_type: 'pdf', text, needs_ocr: false,
              page_count: parsed.numpages || 1, images: [] };
    } else {
      // Scanned PDF -> rasterize each page to PNG, hand images to OCR node (R1)
      const workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ocr-'));
      execFileSync('pdftoppm', ['-png', '-r', '150', filePath, path.join(workDir, 'page')]);
      const files = fs.readdirSync(workDir).filter(f => f.endsWith('.png'))
                      .sort((a, b) => pageNum(a) - pageNum(b));
      const images = files.map(f => ({
        page_number: pageNum(f),
        data_url: dataUrl(fs.readFileSync(path.join(workDir, f)), 'image/png'),
      }));
      out = { ...passthrough, source_type: 'pdf', text: '', needs_ocr: true,
              page_count: images.length, images };
    }

  } else {
    // png / jpg / jpeg -> single-image OCR
    const mime = ext === 'png' ? 'image/png' : 'image/jpeg';
    out = { ...passthrough, source_type: ext, text: '', needs_ocr: true, page_count: 1,
            images: [{ page_number: 1, data_url: dataUrl(fs.readFileSync(filePath), mime) }] };
  }
} catch (e) {
  // read / parse / rasterize failures are runtime -> 5xx
  throw new Error(`Extraction failed for ${source_name}: ${e.message}`);
}

return [{ json: out }];

// n8n Function node: "Chunk"
// Passthrough (conversation_id, tenant_id, ...) is read directly from the
// "Extract Text" node, so it survives the OCR HTTP call with NO reliance on any
// "Include Input Fields" toggle. Text comes from the current item: Extract's
// text on the non-OCR branch, or the OCR response (choices) on the OCR branch.
// 512-word windows, 50-word overlap (MODULE_SPEC_M5).
const ex = $('Extract Text').first().json;   // passthrough + needs_ocr (both branches)
const cur = items[0].json;                    // Extract output OR OCR response
const used_ocr = ex.needs_ocr === true;

let text = (typeof cur.text === 'string' && cur.text.trim().length)
  ? cur.text
  : (cur.choices && cur.choices[0] && cur.choices[0].message
      ? (cur.choices[0].message.content || '')
      : '');
text = String(text).trim();

if (!text.length) {
  throw new Error(`No extractable text for ${ex.source_name}`);   // -> 5xx (runtime)
}

const CHUNK_SIZE = 512;   // words
const OVERLAP = 50;
const words = text.split(/\s+/).filter(Boolean);
const chunks = [];
let i = 0;
while (i < words.length) {
  chunks.push({
    content: words.slice(i, i + CHUNK_SIZE).join(' '),
    chunk_index: chunks.length,
    page_number: null,     // page boundaries lost after concat; metadata.page_number optional
  });
  i += (CHUNK_SIZE - OVERLAP);
}

return [{
  json: {
    chunks,
    conversation_id: ex.conversation_id,
    tenant_id: ex.tenant_id,
    source_name: ex.source_name,
    ttl_seconds: ex.ttl_seconds,
    used_ocr,
  },
}];

// n8n Function node: "Zip Rows"
// chunks[] + passthrough are read directly from the "Chunk" node; only the
// embeddings (data[]) come from the current item (Voyage response). NO reliance
// on any "Include Input Fields" toggle. Explodes to N row items whose field
// order matches the $1..$8 INSERT contract.
const chunkOut = $('Chunk').first().json;
const cur = items[0].json;                   // Voyage response: { data: [{embedding, index}, ...] }
const chunks = chunkOut.chunks || [];
const data = (cur.data || []).slice();

if (!chunks.length) {
  throw new Error('Zip Rows: no chunks to store');   // -> 5xx
}
if (data.length !== chunks.length) {
  throw new Error(`Embedding count mismatch: ${data.length} for ${chunks.length} chunks`); // -> 5xx
}

data.sort((a, b) => (a.index ?? 0) - (b.index ?? 0));   // defensive: align by Voyage index

const { tenant_id, conversation_id, source_name, ttl_seconds, used_ocr } = chunkOut;

return chunks.map((c, i) => {
  const vec = data[i].embedding;
  if (!Array.isArray(vec) || vec.length !== 1024) {
    throw new Error(`Bad embedding for chunk ${i}: expected 1024 dims`);   // -> 5xx
  }
  return {
    json: {
      tenant_id,                                 // $1  isolation gate (rule 3)
      conversation_id,                           // $2
      content: c.content,                        // $3
      embedding: `[${vec.join(',')}]`,           // $4  ::vector literal
      chunk_index: c.chunk_index,                // $5
      source_name,                               // $6
      metadata: JSON.stringify({                 // $7  ::jsonb
        used_ocr: used_ocr === true,
        page_number: c.page_number ?? null,
      }),
      ttl_seconds,                               // $8
    },
  };
});

// n8n Function node: "Format success"
// Sits between Store ephemeral and Respond (success). Builds the locked §B
// success body. Postgres RETURNING gives expires_at (+ one item per inserted
// row); conversation_id / used_ocr are pulled from the Chunk node (Postgres
// output doesn't carry them).
const rows = items;                          // one item per inserted ephemeral_chunks row
const chunk_count = rows.length;

if (!chunk_count) {
  throw new Error('Format success: no rows were inserted');   // -> 5xx via Format Error
}

const rawExpires = rows[0].json.expires_at;
const expires_at = (rawExpires instanceof Date) ? rawExpires.toISOString() : rawExpires;

const chunkMeta = $('Chunk').first().json;

return [{
  json: {
    status: 'completed',
    conversation_id: chunkMeta.conversation_id,
    chunk_count,
    used_ocr: chunkMeta.used_ocr === true,
    expires_at,
  },
}];

// n8n Function node: "Format Error"
// All error outputs converge here. Classify 422 (validation) vs 5xx (runtime)
// and emit the locked failure body. Respond (failure) reads statusCode.
const j = items[0].json || {};

// n8n error-output shape varies -- dig the thrown message out of the likely spots
const msg =
  (j.error && (j.error.message || j.error.description)) ||
  (typeof j.error === 'string' ? j.error : null) ||
  j.message ||
  'Unexpected error during ephemeral ingestion';

// Validation messages from Validate + Extract Text -> 422; everything else -> 5xx.
// .includes (not .startsWith) so an n8n-prepended node label doesn't break matching.
const VALIDATION_MARKERS = [
  'Missing required field',
  'file_path outside allowed roots',
  'File exceeds 10 MB limit',
  'ttl_seconds',                  // "out of range" / "must be an integer"
  'Unsupported file type',
];
const isValidation = VALIDATION_MARKERS.some(m => String(msg).includes(m));

return [{
  json: {
    status: 'failed',
    error: String(msg),
    statusCode: isValidation ? 422 : 500,
  },
}];
